sys_script_include.script:
var CareMilestoneService = Class.create();

CareMilestoneService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    /**
     * Check whether a Care Milestone exists.
     *
     * @param {String} milestoneSysId
     * @return {Boolean}
     */
    milestoneExists: function(milestoneSysId) {

        if (this.validationUtils.isEmpty(milestoneSysId)) {
            return false;
        }

        var milestone = new GlideRecord(
            'x_2130921_caresy_0_care_milestone'
        );

        if (!milestone.isValid()) {
            gs.error(
                'CareMilestoneService: Care Milestone table is invalid.'
            );
            return false;
        }

        return milestone.get(milestoneSysId);
    },

    /**
     * Retrieve a Care Milestone.
     *
     * @param {String} milestoneSysId
     * @return {GlideRecord|null}
     */
    getMilestone: function(milestoneSysId) {

        if (this.validationUtils.isEmpty(milestoneSysId)) {
            return null;
        }

        var milestone = new GlideRecord(
            'x_2130921_caresy_0_care_milestone'
        );

        if (!milestone.isValid()) {
            gs.error(
                'CareMilestoneService: Care Milestone table is invalid.'
            );
            return null;
        }

        if (milestone.get(milestoneSysId)) {
            return milestone;
        }

        return null;
    },

    /**
     * Check whether a Care Milestone is currently active.
     *
     * @param {String} milestoneSysId
     * @return {Boolean}
     */
    isMilestoneActive: function(milestoneSysId) {

        var milestone = this.getMilestone(milestoneSysId);

        if (!milestone) {
            return false;
        }

        return milestone.getValue('active') == '1';
    },

    type: 'CareMilestoneService'
};
